const normalizeHeaders = (headers = {}) => {
  const entries = Object.entries(headers || {});
  return Object.fromEntries(
    entries.map(([key, value]) => [String(key || '').toLowerCase(), value])
  );
};

return items.map((item) => {
  const root = item.json || {};
  const body =
    root.body && typeof root.body === 'object'
      ? root.body
      : root;
  const headers = normalizeHeaders(
    root.headers && typeof root.headers === 'object' ? root.headers : {}
  );

  const authHeaderName = String($env.N8N_WEBHOOK_AUTH_HEADER || 'x-api-key')
    .trim()
    .toLowerCase();

  const payload =
    body.payload && typeof body.payload === 'object'
      ? body.payload
      : {};

  return {
    json: {
      eventType: String(body.eventType || ''),
      outcome: String(body.outcome || '').toLowerCase(),
      occurredAt: String(body.occurredAt || new Date().toISOString()),
      source: String(body.source || ''),
      request: {
        route: String(body.request?.route || ''),
        method: String(body.request?.method || ''),
        ip: String(body.request?.ip || ''),
        requestId: String(body.request?.requestId || ''),
        userAgent: String(body.request?.userAgent || ''),
        referer: String(body.request?.referer || ''),
        origin: String(body.request?.origin || '')
      },
      payload,
      authToken: String(headers[authHeaderName] || '')
    }
  };
});

const expectedToken = String($env.N8N_WEBHOOK_AUTH_TOKEN || '').trim();

if (!expectedToken) {
  return items;
}

return items.filter((item) => {
  const actualToken = String(item.json.authToken || '').trim();
  return actualToken === expectedToken;
});

return items.map((item) => {
  const event = item.json || {};
  const payload = event.payload || {};

  return {
    json: {
      eventType: event.eventType,
      outcome: event.outcome,
      occurredAt: event.occurredAt,
      source: event.source,
      route: event.request?.route || '',
      requestId: event.request?.requestId || '',
      requestIp: event.request?.ip || '',
      languageHint: String(payload.languageHint || ''),
      model: String(payload.model || ''),
      provider: String(payload.provider || ''),
      latencyMs: Number(payload.latencyMs || 0),
      errorCode: String(payload.errorCode || ''),
      errorMessage: String(payload.errorMessage || ''),
      rawEvent: event
    }
  };
});

const logUrl = String($env.N8N_EVENT_LOG_URL || '').trim();
if (!logUrl) return [];
return items;

return items.map((item) => {
  const event = item.json || {};

  const lines = [
    '🚨 Portfolio AI Event Failed',
    `Type: ${event.eventType || '-'}`,
    `Route: ${event.route || '-'}`,
    `Request ID: ${event.requestId || '-'}`,
    `Code: ${event.errorCode || '-'}`,
    `Message: ${event.errorMessage || '-'}`,
    `Latency: ${event.latencyMs || 0}ms`,
    `At: ${event.occurredAt || '-'}`,
  ];

  return {
    json: {
      ...event,
      alertText: lines.join('\n'),
    }
  };
});

const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chatId = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chatId) return [];
return items;

const apiKey = String($env.RESEND_API_KEY || '').trim();
const mailFrom = String($env.ALERT_EMAIL_FROM || '').trim();
const mailTo = String($env.ALERT_EMAIL_TO || '').trim();
if (!apiKey || !mailFrom || !mailTo) return [];
return items;
